package com.nigson.acceptance.provider;

import java.time.*;import java.util.*;import tools.jackson.databind.JsonNode;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.integration.provider.*;import com.nigson.integration.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;
import static org.assertj.core.api.Assertions.*;

class CareerSheetSyncPersistenceTest {
 private JdbcTemplate jdbc;private JobRepository jobs;private TransactionTemplate tx;private SheetSyncRepository records;private JobExecution execution;private AuditWriter audit;private Clock clock;private final List<UUID> jobIds=new ArrayList<>();private final List<UUID> applicationIds=new ArrayList<>();private static final String SHEET="synthetic-sheet-001";private static final String GROUP="synthetic-career-group";
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"isolated Integration PostgreSQL required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_INTEGRATION_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);clock=Clock.systemUTC();var metrics=new SimpleMeterRegistry();jobs=new JdbcJobRepository(jdbc,clock);audit=new AuditWriter(jdbc,clock,metrics);records=new SheetSyncRepository(jdbc,manager,clock);execution=new JobExecution(jdbc,manager,jobs,audit,clock,metrics);}
 @AfterEach void clean(){for(UUID id:applicationIds)jdbc.update("DELETE FROM integration.sheet_sync_record WHERE application_id=?",id);for(UUID id:jobIds)jdbc.update("DELETE FROM integration.integration_job WHERE id=?",id);}
 private UUID app(){UUID id=UUID.randomUUID();applicationIds.add(id);return id;}
 private JsonNode event(UUID app,UUID opportunity,String group){var root=EventCodec.JSON.createObjectNode().put("event_id",UUID.randomUUID().toString()).put("event_type","career.application.created.v1").put("schema_version",1).put("producer","experience").put("occurred_at",clock.instant().toString()).put("aggregate_id",app.toString()).put("aggregate_version",0).putNull("organization_id").put("correlation_id",UUID.randomUUID().toString()).putNull("traceparent");root.set("payload",EventCodec.JSON.createObjectNode().put("application_id",app.toString()).put("opportunity_id",opportunity.toString()).put("recipient_group",group));return root;}
 private JobRepository.Record enqueue(UUID app){String key="career-sheet:"+app+":"+GROUP;var saved=tx.execute(s->jobs.enqueueTracked(JobValues.Kind.SHEETS_SYNC,key,"experience",app));jobIds.add(saved.job().id());return saved.job();}
 private CareerSheetContextClient.Context context(UUID app,String applicant){return new CareerSheetContextClient.Context(app,"Engineer",applicant,"candidate@example.invalid",clock.instant().toString(),"SUBMITTED",new TreeMap<>(Map.of("portfolio","=HYPERLINK(\"https://private.example.invalid\")")));}
 @Test void careerEventCreatesOneOwnerLocalStableJobAndRejectsUnconfiguredRecipient(){UUID app=app(),op=UUID.randomUUID();var handler=new CareerApplicationCreatedHandler(jobs,audit,GROUP);var e=event(app,op,GROUP);tx.execute(s->{assertThat(handler.handle(jdbc,e)).isEqualTo("APPLIED");assertThat(handler.handle(jdbc,e)).isEqualTo("APPLIED");return null;});var found=tx.execute(s->jdbc.queryForList("SELECT id,kind,owner_service,business_key,resource_id FROM integration.integration_job WHERE resource_id=?",app));assertThat(found).hasSize(1);assertThat(found.getFirst().get("kind")).isEqualTo("SHEETS_SYNC");assertThat(found.getFirst().get("owner_service")).isEqualTo("experience");assertThat(found.getFirst().get("business_key")).isEqualTo("career-sheet:"+app+":"+GROUP);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,found.getFirst().get("id"))).isEqualTo(1);assertThatThrownBy(()->tx.execute(s->new CareerApplicationCreatedHandler(jobs,audit,"approved-other-group").handle(jdbc,e))).isInstanceOf(Problem.Failure.class);}
 @Test void acceptedWriteTimeoutIsReconciledByStableApplicationRowWithoutDuplicate(){UUID app=app();var job=enqueue(app);var provider=new StatefulGoogleSheetsMock();var correlation=UUID.randomUUID();var sync=new CareerSheetSyncHandler((id,c)->context(id,"=Formula Candidate"),records,provider,SHEET,new byte[32]);var claim=execution.claim(Set.of(JobValues.Kind.SHEETS_SYNC),1,Duration.ofSeconds(60)).getFirst();provider.timeoutAfterNextAcceptedWrite();var uncertain=sync.execute(claim);assertThat(uncertain.state()).isEqualTo(JobValues.State.UNKNOWN);assertThat(execution.finish(claim,JobHandler.Provider.GOOGLE_SHEETS,uncertain,correlation)).isTrue();assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.UNKNOWN);assertThat(jdbc.queryForObject("SELECT state FROM integration.sheet_sync_record WHERE application_id=?",String.class,app)).isEqualTo("PENDING");assertThat(provider.rowCount(SHEET)).isEqualTo(1);jdbc.update("UPDATE integration.integration_job SET next_attempt_at=? WHERE id=?",java.sql.Timestamp.from(clock.instant().minusSeconds(1)),job.id());var retry=execution.claim(Set.of(JobValues.Kind.SHEETS_SYNC),1,Duration.ofSeconds(60)).getFirst();assertThat(retry.uncertain()).isTrue();var reconciled=sync.reconcile(retry);assertThat(reconciled.state()).isEqualTo(JobValues.State.SUCCEEDED);assertThat(execution.finish(retry,JobHandler.Provider.GOOGLE_SHEETS,reconciled,correlation)).isTrue();assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.SUCCEEDED);assertThat(jdbc.queryForObject("SELECT state FROM integration.sheet_sync_record WHERE application_id=?",String.class,app)).isEqualTo("SYNCED");assertThat(provider.rowCount(SHEET)).isEqualTo(1);var cells=provider.row(SHEET,app.toString()).orElseThrow().cells();assertThat(cells.get(2)).isEqualTo("'=Formula Candidate");assertThat(cells.get(6)).contains("=HYPERLINK").doesNotStartWith("=");}
 @Test void sheetRecordKeepsOneStableRowAndFencesStaleOutcome(){UUID app=app();String hash="a".repeat(64),changed="b".repeat(64);var first=records.prepare(app,SHEET,hash);var done=records.synced(first);assertThat(done.state()).isEqualTo("SYNCED");assertThat(done.rowKey()).isEqualTo(app.toString());var refreshed=records.prepare(app,SHEET,changed);assertThat(refreshed.id()).isEqualTo(first.id());assertThat(refreshed.version()).isEqualTo(done.version()+1);assertThat(refreshed.state()).isEqualTo("PENDING");assertThatThrownBy(()->records.synced(done)).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.VERSION_MISMATCH);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.sheet_sync_record WHERE application_id=? AND spreadsheet_key=?",Integer.class,app,SHEET)).isEqualTo(1);}
}
